<script setup lang="tsx">
import { nextTick, WatchStopHandle } from "vue";
import { onBeforeUnmount, onMounted, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsInfo } from "@/util/tips";
import { GetContestProblemIndexStr, GetContestStatistics } from "@/apis/contest.ts";

import { GetJudgeStatusColor, GetJudgeStatusStr, IsJudgeStatusRunning, JudgeStatus } from "@/apis/judge.ts";

// 使用统一的 echarts 按需引入实例
import echarts from "@/util/echarts";
import { handleGotoContestProblem } from "@/util/router.ts";
import { GetJudgeLanguageStr, GetSubmitLanguages, JudgeLanguage } from "@/apis/language.ts";
import { useBreakpoint } from "@/composables/useBreakpoint";

const route = useRoute();
const router = useRouter();
const { globalProperties } = useCurrentInstance();
const { isMobile } = useBreakpoint();

// echarts 容器 ref，用于替代 getElementById
const countStatisticsRef = ref<HTMLElement | null>(null);
const languageStatisticsRef = ref<HTMLElement | null>(null);
const statisticsCharts = ref<echarts.ECharts[]>([]);

const watchHandle: WatchStopHandle | null = null;

let contestId = 0;
const contestLoading = ref(false);
const contestData = ref([]);

const allOptions = [{ label: "全部语言", value: undefined }] as { label: string; value: JudgeLanguage | undefined }[];
const languageOptions = ref([] as { label: string; value: JudgeLanguage | undefined }[]);
languageOptions.value = GetSubmitLanguages();
languageOptions.value = allOptions.concat(languageOptions.value);

const searchForm = ref({
  language: undefined as JudgeLanguage | undefined,
});

const listColumns = ref([] as any[]);

const loadCountStatistics = (countData: { [key: string]: number }) => {
  const dateValues = [];
  const acceptValues = [];
  const attemptValues = [];
  let lastAcceptValue = 0;
  let lastAttemptValue = 0;
  for (const item of countData) {
    const date = new Date(item.date);
    const dataDayString = date.toLocaleString();
    dateValues.push(dataDayString);
    // attempt from backend is COUNT(*) which includes AC submissions;
    // for stacked chart, non-AC attempts = total - accept
    const accept = item.accept;
    const nonAccept = item.attempt - item.accept;
    acceptValues.push(accept + lastAcceptValue);
    attemptValues.push(nonAccept + lastAttemptValue);
    lastAcceptValue += accept;
    lastAttemptValue += nonAccept;
  }

  const chartDom = countStatisticsRef.value;
  if (!chartDom) return;
  const myChart = echarts.init(chartDom);
  const option = {
    title: {
      text: "提交数量",
    },
    tooltip: {
      trigger: "axis",
      axisPointer: {
        type: "cross",
        label: {
          backgroundColor: "#6a7985",
        },
      },
    },
    legend: {
      data: ["Accept", "Unaccept"],
    },
    toolbox: {
      feature: {
        saveAsImage: {},
      },
    },
    xAxis: [
      {
        type: "category",
        boundaryGap: false,
        data: dateValues,
      },
    ],
    yAxis: [
      {
        type: "value",
      },
    ],
    series: [
      {
        name: "Accept",
        type: "line",
        stack: "Total",
        color: "#2ecc71",
        areaStyle: {},
        emphasis: {
          focus: "series",
        },
        data: acceptValues,
      },
      {
        name: "Unaccept",
        type: "line",
        stack: "Total",
        color: "#409EFF",
        label: {
          show: true,
          position: "top",
          // Show label at first/last/every-5th point; display cumulative total (AC + non-AC)
          formatter: (params: any) => {
            if (params.dataIndex === 0 || params.dataIndex === attemptValues.length - 1 || params.dataIndex % 5 === 0) {
              return acceptValues[params.dataIndex] + attemptValues[params.dataIndex];
            }
            return "";
          }
        },
        areaStyle: {},
        emphasis: {
          focus: "series",
        },
        data: attemptValues,
      },
    ],
  };

  myChart.setOption(option);

  const resizeObserver = new ResizeObserver(() => {
    myChart.resize({
      height: 400
    });
  });
  resizeObserver.observe(chartDom);
};

const loadLanguageStatistics = (languageData: { [key: string]: number }) => {
  const chartDom = languageStatisticsRef.value;
  if (!chartDom) return;
  const myChart = echarts.init(chartDom);

  const dataList = [] as { name: string; value: number }[];
  Object.keys(languageData).forEach((key) => {
    dataList.push({
      name: GetJudgeLanguageStr(Number(key)),
      value: languageData[key],
    });
  });

  const option = {
    title: {
      text: "语言使用统计",
      left: "center",
    },
    tooltip: {
      trigger: "item",
    },
    legend: {
      orient: "vertical",
      left: "left",
    },
    series: [
      {
        name: "语言",
        type: "pie",
        radius: "50%",
        data: dataList,
        emphasis: {
          itemStyle: {
            shadowBlur: 10,
            shadowOffsetX: 0,
            shadowColor: "rgba(0, 0, 0, 0.5)",
          },
        },
      },
    ],
  };

  myChart.setOption(option);

  const resizeObserver = new ResizeObserver(() => {
    myChart.resize({
      height: 325
    });
  });
  resizeObserver.observe(chartDom);
};

const fetchContestData = async () => {
  contestLoading.value = true;

  const res = await GetContestStatistics(contestId, searchForm.value.language);
  if (res.code !== 0) {
    contestLoading.value = false;
    ShowErrorTips(globalProperties, res.code);
    await router.push({ name: "contest" });
    return;
  }
  if (!res.data.has_auth) {
    ShowTextTipsInfo(globalProperties, "您目前没有权限查看比赛统计");
    await router.push({ name: "contest-detail", params: { contestId: contestId } });
    return;
  }
  const statisticsList = res.data.statistics;

  statisticsList.sort((a, b) => {
    return a.index - b.index;
  });

  contestData.value = [];
  statisticsList.forEach((item) => {
    const statistics = item.statistics as { [key: number]: number };
    const elment = {
      index: item.index,
      key: GetContestProblemIndexStr(item.index),
    } as Record<string, any>;
    Object.values(JudgeStatus).forEach((status) => {
      if (typeof status === "number" && statistics && statistics[status]) {
        elment[status] = statistics[status];
      } else if (typeof status === "number") {
        elment[status] = "-";
      }
    });
    contestData.value.push(elment);
  });

  loadCountStatistics(res.data.count);
  loadLanguageStatistics(res.data.language);

  nextTick(function () {
    const allDoms = document.getElementsByClassName("echart-statistics");
    statisticsCharts.value = [];
    for (let i = 0; i < allDoms.length; i++) {
      const chartDom = allDoms[i] as HTMLElement;
      const myChart = echarts.init(chartDom);

      const statistics = statisticsList[i].statistics;

      const colors = [] as string[];
      const dataList = [] as { name: string; value: number }[];
      Object.values(JudgeStatus).forEach((status) => {
        if (typeof status === "number" && statistics && statistics[status]) {
          colors.push(GetJudgeStatusColor(status));
          dataList.push({
            name: GetJudgeStatusStr(status),
            value: (statistics && statistics[status]) || 0,
          });
        }
      });

      const option = {
        tooltip: {
          trigger: "item",
        },
        color: colors,
        series: [
          {
            type: "pie",
            radius: "50%",
            data: dataList,
            emphasis: {
              itemStyle: {
                shadowBlur: 10,
                shadowOffsetX: 0,
                shadowColor: "rgba(0, 0, 0, 0.5)",
              },
            },
          },
        ],
      };
      myChart.setOption(option);
      statisticsCharts.value.push(myChart);
    }
  });

  contestLoading.value = false;
};

const handleSearchFormSubmit = () => {
  fetchContestData();
};

const handleSearchFormReset = () => {
  searchForm.value.language = undefined;
};

// 列表列构建：移动端隐藏"统计"列（内嵌 echarts 300px 宽度会撑爆窄屏）
const buildListColumns = () => {
  listColumns.value = [
    {
      title: "题目",
      colKey: "index",
      cell: (_: any, data: any) => {
        return (
          <t-button variant="dashed" onClick={async () => await handleGotoContestProblem(contestId, data.row.index)}>
            {data.row.key}
          </t-button>
        );
      },
    },
  ];
  if (!isMobile.value) {
    listColumns.value.push({
      title: "统计",
      colKey: "statistics",
      cell: (_: any, _data: any) => {
        return <div class="echart-statistics" style="width: 300px;height: 200px;"></div>;
      },
    });
  }

  const excludeStatuses = [JudgeStatus.Unknown, JudgeStatus.Max];
  Object.values(JudgeStatus).forEach((status) => {
    if (excludeStatuses.includes(status as JudgeStatus)) {
      return;
    }
    if (typeof status !== "number") {
      return;
    }
    if (IsJudgeStatusRunning(status)) {
      return;
    }
    listColumns.value.push({
      title: GetJudgeStatusStr(status),
      colKey: status,
    });
  });
};

onMounted(async () => {
  if (Array.isArray(route.params.contestId)) {
    contestId = Number(route.params.contestId[0]);
  } else {
    contestId = Number(route.params.contestId);
  }
  if (!contestId) {
    await router.push({ name: "contest" });
    return;
  }

  buildListColumns();
  await nextTick();
  await fetchContestData();
});

// 断点切换时重建列；切到桌面端时统计列会重新渲染，需要重新拉数据并初始化 echarts
watch(isMobile, () => {
  buildListColumns();
  nextTick(() => {
    if (contestId) {
      fetchContestData();
    }
  });
});

onBeforeUnmount(() => {
  if (watchHandle) {
    watchHandle();
  }
});
</script>

<template>
  <t-row>
    <t-col :span="isMobile ? 12 : 7">
      <t-card class="sh-card"><div ref="countStatisticsRef" style="min-height: 400px"></div></t-card>
    </t-col>
    <t-col :span="isMobile ? 12 : 5">
      <t-card class="sh-card">
        <t-form :layout="isMobile ? 'vertical' : 'inline'" @submit="handleSearchFormSubmit" @reset="handleSearchFormReset">
          <t-form-item label="语言">
            <t-select v-model="searchForm.language" placeholder="请选择提交语言" auto-width clearable>
              <t-option v-for="item in languageOptions" :key="item.value" :value="item.value" :label="item.label"></t-option>
            </t-select>
          </t-form-item>
          <t-form-item>
            <t-space>
              <t-button theme="primary" type="submit">搜索</t-button>
              <t-button theme="default" variant="base" type="reset">重置</t-button>
            </t-space>
          </t-form-item>
        </t-form>
      </t-card>
      <t-card class="sh-card"><div ref="languageStatisticsRef" style="min-height: 200px"></div></t-card>
    </t-col>
  </t-row>

      <t-card style="margin: 10px">
        <div class="sh-table-wrapper">
          <t-table
            :data="contestData"
            :columns="listColumns"
            row-key="id"
            vertical-align="middle"
            :hover="true"
            :loading="contestLoading"
            table-layout="auto"
            style="white-space: nowrap"
          />
        </div>
      </t-card>
</template>

<style scoped>
.sh-card {
  margin: 10px;
}

.sh-table-wrapper {
  width: 100%;
  overflow-x: auto;
}

@media (max-width: 800px) {
  .sh-card {
    margin: 8px 4px;
  }
}
</style>
